const item = $input.first().json;
const body = item.body ?? item;
const all  = body.all_fields ?? {};
const rule = all.rule ?? {};
const agent= all.agent ?? {};
const data = all.data  ?? {};

const rule_id    = rule.id || body.rule_id || '';
const rule_desc  = rule.description || body.title || body.rule_desc || '';
const level      = rule.level || body.level || 0;
const agent_name = agent.name || body.agent_name || 'unknown';
const mitre_str  = JSON.stringify(rule.mitre || body.mitre || {});
const timestamp  = all.timestamp || body.timestamp || '';
const alert_id   = String(body.id || all.id || (rule_id + '|' + timestamp));
// Dedup key: rule_id + minute bucket (same alert double-posted = same minute; new attack later = new minute)
const minuteBucket = String(timestamp).slice(0, 16); // YYYY-MM-DDTHH:MM
const dedup_key  = rule_id + '|' + minuteBucket;
const raw_dt     = JSON.stringify(all).slice(0, 2500);

return [{
  json: {
    rule_id,
    rule_desc,
    level: Number(level) || 0,
    agent_name,
    mitre: mitre_str,
    timestamp,
    alert_id,
    dedup_key,
    src_ip:      (data.srcip || data.src_ip || ''),
    dst_ip:      (data.dstip || data.dst_ip || ''),
    file_hash:   (data.syscheck?.md5_after || data.file?.md5 || data.md5 || data.sha256 || data.hash || ''),
    url_or_domain: (data.hostname || data.domain || data.url || ''),
    raw: raw_dt
  }
}];

// Runs ONCE - pulls both sources itself (no multi-branch input bug)
const base = $('Parse Alert').first().json;
let abuse = null;
try { abuse = $('AbuseIPDB Enrichment').first().json?.data ?? null; } catch(e) {}

const llmBody = {
  model: "qwen/qwen3.8-27b",
  messages: [
    { role: "system", content: "You are a senior SOC analyst. Write a concise triage in PLAIN TEXT only (no markdown, no asterisks, no backticks) with these sections: WHAT HAPPENED, TECHNIQUE, SEVERITY, NEXT STEPS, FP LIKELIHOOD. Max 200 words. Be direct." },
    { role: "user", content: "ALERT: " + (base.rule_desc || 'unknown') + " | RULE: " + base.rule_id + " | LEVEL: " + base.level + " | AGENT: " + base.agent_name + " | MITRE: " + (base.mitre || 'none') + " | SRC IP: " + (base.src_ip || 'none') + " | HASH: " + (base.file_hash || 'none') + " | ENRICHMENT: " + (abuse ? JSON.stringify(abuse).slice(0,400) : 'none') }
  ]
};

return [{ json: { ...base, enrichment: abuse, llm_body: JSON.stringify(llmBody) } }];

const ai = $input.first().json;
const base = $('Parse Alert').first().json;

// Extract LLM content
let summary = '';
try { summary = ai.choices[0].message.content || ''; } catch(e) {}
if (!summary) summary = 'Summary unavailable';

// --- Markdown -> plain text (strip ** __ ` # and stray artifacts) ---
summary = summary
  .replace(/\*\*?/g, '')          // bold/italic asterisks
  .replace(/__/g, '')              // underscores emphasis
  .replace(/`{1,3}/g, '')          // code ticks
  .replace(/^#+\s*/gm, '')         // markdown headers
  .replace(/^\s*[-*]\s+/gm, '  • ')  // bullets -> dots
  .replace(/\n{3,}/g, '\n\n')     // collapse blank lines
  .trim();

// Truncate overly long summaries (Telegram 4096 char limit, keep room for header)
if (summary.length > 2800) summary = summary.slice(0, 2800) + '\n… (truncated)';

// --- Clean header fields ---
const desc = (base.rule_desc || 'Unknown alert').replace(/^[^:]{0,30}:\s*/, '').trim();

let mitre = 'none';
try {
  const m = JSON.parse(base.mitre || '{}');
  const ids = m.id || [];
  const tactics = m.tactic || [];
  if (ids.length) mitre = ids.map((t,i)=> t + (tactics[i] ? ' ('+tactics[i]+')' : '')).join(', ');
} catch(e) {}

const esc = s => String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const msg = [
  '<b>🚨 SOC ALERT</b>',
  '<i>' + esc(desc) + '</i>',
  '',
  '<b>Rule:</b> ' + esc(base.rule_id) + '   <b>Level:</b> ' + esc(base.level),
  '<b>Host:</b> ' + esc(base.agent_name),
  '<b>MITRE:</b> ' + esc(mitre),
  '<b>Time:</b> ' + esc(base.timestamp),
  '',
  '<b>🤖 AI Triage</b>',
  esc(summary)
].join('\n');

return [{ json: { chat_id: 'REDACTED', text: msg } }];
